#include "Dsp.h"
#include <memory>
#include <iostream>
#include <vector>
#include <chrono>
int fails=0;void check(bool b,const char* n,double v=0){std::cout<<(b?"PASS ":"FAIL ")<<n<<" : "<<v<<"\n";fails+=!b;}
double response(float sr,float frequency,bool hp,int index){pong::CutBank f;f.setup(sr,1000,hp);f.weights={};f.weights[index]=1;double in=0,out=0;for(int n=0;n<24000;++n){float x=float(.2*std::sin(2*3.141592653589793*double(frequency)*n/double(sr)));float y=f.tick(x,float(12<<index),0);if(n>12000){in+=double(x)*x;out+=double(y)*y;}}return 10*std::log10(out/in);}
int main(){
 double worst=0;for(float sr:{44100.f,48000.f,88200.f,96000.f})for(int type=0;type<4;++type)for(bool hp:{false,true}){double cutoff=response(sr,1000,hp,type);worst=std::max(worst,std::abs(cutoff+3.0102999566));float f=sr/pong::pi*std::atan(std::tan(pong::pi*1000/sr)*(hp?.5f:2.f));double stop=response(sr,f,hp,type),expected=-10*std::log10(1+std::pow(2.,2*(2<<type)));worst=std::max(worst,std::abs(stop-expected));}check(worst<.15,"Butterworth cut calibration across 4 rates / 4 slopes / HP+LP",worst);
 pong::Saturator4x os;double rawCos=0,rawSin=0,osCos=0,osSin=0;for(int n=0;n<60000;++n){float x=.8f*std::sin(2*pong::pi*9000*n/48000);float raw=pong::Saturator4x::curve(4*x)/4,over=os.process(x,1,1);if(n>=12000){double phase=2*3.141592653589793*3000*n/48000;rawCos+=raw*std::cos(phase);rawSin+=raw*std::sin(phase);osCos+=over*std::cos(phase);osSin+=over*std::sin(phase);}}double alias=20*std::log10(std::hypot(osCos,osSin)/std::hypot(rawCos,rawSin));check(alias<-6,"4x OS reduces folded fifth harmonic for 9 kHz probe (dB)",alias);
 pong::Limiter limiter;float ceiling=pong::gain(-1),peak=0;for(int n=0;n<10000;++n){auto y=limiter.tick({n%131==0?100000.f:.2f,-1000.f},ceiling,48000);peak=std::max({peak,std::abs(y[0]),std::abs(y[1])});}check(peak<=ceiling,"linked lookahead sample ceiling under overload",peak);
 auto e=std::make_unique<pong::Engine>();e->midi(1,60,.5f);e->midi(1,64,.8f);check(e->note==64,"MIDI last-note priority");e->midi(0,64,0);check(e->note==60,"MIDI release falls back to held note");e->midi(1,60,0);check(e->note==-1,"velocity zero releases note");e->midi(2,1,.75f);check(e->cc==.75f,"MIDI CC input");
 e->target[1][pong::Threshold]=-30;e->target[1][pong::Ratio]=8;e->detectorSource[1]=2;e->prepare(48000);for(int n=0;n<60000;++n)e->tick({.01f,.01f},2,.8f);check(e->reduction[1]>10,"external sidechain controls GR",e->reduction[1]);
 e=std::make_unique<pong::Engine>();e->global[pong::Adapt]=1;e->global[pong::Recovery]=.3f;e->target[1][pong::Drive]=48;e->prepare(48000);for(int n=0;n<96000;++n)e->tick({.2f*std::sin(n*.05f),0},1);check(e->effective[1][pong::Drive]<40,"adaptive drive reduction under sustained stress",e->effective[1][pong::Drive]);float held=e->adaptive[1];e->global[pong::Hold]=1;for(int n=0;n<6000;++n)e->tick({0,0},1);check(e->adaptive[1]==held,"HOLD freezes adaptive state");e->global[pong::Hold]=0;for(int n=0;n<240000;++n)e->tick({0,0},1);check(e->adaptive[1]<.01,"adaptive recovery in silence",e->adaptive[1]);
 auto run=[](int block){auto e=std::make_unique<pong::Engine>();e->global[pong::Play]=1;e->global[pong::Adapt]=.5f;e->global[pong::Send]=.2f;e->target[1][pong::Colour]=.5f;e->routes[0]={0,1,1,-.5f,30};e->prepare(48000);std::vector<float> out(96000);for(int offset=0;offset<96000;offset+=block)for(int n=offset;n<std::min(offset+block,96000);++n){if(n==700)e->midi(1,72,.8f);out[n]=e->tick({.2f*std::sin(n*.1f),0},1)[0];}return out;};auto a=run(32),b=run(1024);float error=0;for(int n=0;n<96000;++n)error=std::max(error,std::abs(a[n]-b[n]));check(error==0,"PLAY/matrix/hall identical across blocks 32 and 1024",error);
 for(int mode=0;mode<3;++mode){e=std::make_unique<pong::Engine>();e->global[pong::HallPos]=float(mode);e->global[pong::Send]=.6f;e->global[pong::Return]=.5f;e->prepare(48000);double energy=0;for(int n=0;n<96000;++n){auto out=e->tick({n==0?.5f:0,0},1);if(n>10000)energy+=out[0]*out[0];}check(energy>1.e-8&&std::isfinite(energy),"plate audible finite tail in each routing position",energy);}
 e=std::make_unique<pong::Engine>();e->global[pong::Play]=1;e->global[pong::Speed]=4;e->global[pong::GlueColour]=.5f;e->global[pong::GlueComp]=.5f;for(auto&t:e->target){t[pong::Colour]=.8f;t[pong::Drive]=12;}e->prepare(48000);auto start=std::chrono::steady_clock::now();float maxPulse=0;for(int n=0;n<48000*10;++n){e->tick({.2f*std::sin(n*.05f),.2f*std::sin(n*.07f)},2);maxPulse=std::max(maxPulse,e->motion.ball[0].pulse);}double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();check(maxPulse>.25,"Pong collision events generated",maxPulse);check(e->motion.left+e->motion.right>0,"Pong misses update score");std::cout<<"BENCH full colour x5 + GLUE + PLAY 10s stereo: "<<seconds<<" sec / realtime fraction "<<seconds/10<<"\n";
 e=std::make_unique<pong::Engine>();e->routes[0]={14,1,0,-1,5};e->prepare(48000);e->midi(1,60,1);for(int n=0;n<5000;++n)e->tick({.01f,0},1);check(e->effective[1][pong::Drive]<-20,"matrix negative polarity applies to Drive",e->effective[1][pong::Drive]);e->routes[0].band=2;for(int n=0;n<32;++n)e->tick({.01f,0},1);check(e->routeWeights[0][5]>.9f&&e->routeWeights[0][10]<.1f,"route destination change crossfades instead of jumping");
 for(float rate:{44100.f,48000.f,88200.f,96000.f}){e=std::make_unique<pong::Engine>();for(auto&t:e->target){t[pong::Drive]=48;t[pong::Output]=48;t[pong::Range]=48;t[pong::Transient]=48;t[pong::Colour]=1;t[pong::Threshold]=-60;t[pong::Ratio]=30;}e->global[pong::Play]=1;e->global[pong::Adapt]=1;e->global[pong::Send]=1;e->global[pong::Return]=1;e->global[pong::GlueColour]=1;e->global[pong::GlueTrim]=48;e->global[pong::OutputTrim]=48;e->prepare(rate);bool valid=true;float max=0;for(int n=0;n<int(rate);++n){auto y=e->tick({.9f*std::sin(n*.13f),.8f*std::sin(n*.07f)},2,.9f);valid&=std::isfinite(y[0])&&std::isfinite(y[1]);max=std::max({max,std::abs(y[0]),std::abs(y[1])});}check(valid&&max<=pong::gain(-1)+1.e-6f,"all-feature +/-48 dB overload finite and limited",max);}
 std::cout<<"Failures: "<<fails<<"\n";return fails?1:0;
}
